{
  "name": "secret-box",
  "version": "0.1.0",
  "description": "Claude can use a secret without seeing it: a masked box saves keys to the macOS Keychain or Windows Credential Manager (or .env) and gives Claude a placeholder, use_secret loads a stored item as a placeholder, every key a tool prints comes back as a placeholder, and committing .env is refused",
  "author": {
    "name": "David Whitlock",
    "url": "https://github.com/ApisMellow"
  },
  "repository": "https://github.com/ApisMellow/secret-box",
  "license": "MIT",
  "userConfig": {
    "backend": {
      "type": "string",
      "title": "Where the box saves",
      "description": "auto: the macOS Keychain on a Mac, Windows Credential Manager on Windows, the project .env elsewhere. keychain saves to that vault (service = the name, nothing written to .env; macOS and Windows only); dotenv writes the project .env as before",
      "options": [
        "auto",
        "keychain",
        "dotenv"
      ],
      "default": "auto"
    },
    "refuseUnmaskable": {
      "type": "boolean",
      "title": "Refuse Keychain reads it can't hide",
      "description": "macOS and Windows: refuse a Bash command that reads the Keychain (or Credential Manager) in a way secret-box can't pin to one item or hide (a variable, sudo, dump-keychain, security -i, a value under 8 characters). Off, the command runs and only the detector scans its output",
      "default": false
    },
    "listPrefixes": {
      "type": "string",
      "title": "Keychain services list_key_names may show",
      "description": "macOS and Windows: service-name prefixes, separated by commas (myapp/,openai). list_key_names shows the names of Keychain or Credential Manager items whose service starts with one, beside the items secret-box saved. Empty: only those",
      "default": ""
    },
    "keychainAccount": {
      "type": "string",
      "title": "Keychain account",
      "description": "The account the box saves Keychain (or Credential Manager) items under. Empty means your macOS user name ($USER), or on Windows your Windows user name (%USERNAME%)",
      "default": ""
    },
    "secrets": {
      "type": "boolean",
      "title": "Hide secrets",
      "description": "Hide vendor-shaped keys and high-entropy tokens",
      "default": true
    },
    "pii": {
      "type": "boolean",
      "title": "Hide personal information",
      "description": "Hide email addresses and public IP addresses",
      "default": false
    },
    "hideEmails": {
      "type": "boolean",
      "title": "Hide emails",
      "description": "With pii on, also hide email addresses. Turn off to hide only IP addresses",
      "default": true
    },
    "redactPrivateIps": {
      "type": "boolean",
      "title": "Hide private IP addresses",
      "description": "With pii on, also hide private and reserved IP addresses recognized by the detector",
      "default": false
    },
    "restoreInToolInputs": {
      "type": "boolean",
      "title": "Put real values back for tools",
      "description": "Swap a placeholder back for its real value before a tool runs, so commands and file writes keep working",
      "default": true
    },
    "restoreTools": {
      "type": "string",
      "title": "Tools that get real values",
      "description": "Tools that run on this machine and may receive the real value behind a placeholder, separated by commas. Never list a tool that sends its input to another model or the network (Agent, WebFetch, WebSearch)",
      "default": "Bash,Write,Edit,MultiEdit,NotebookEdit"
    },
    "ownApproval": {
      "type": "boolean",
      "title": "Approve calls with real values itself",
      "description": "When a call that got real values put back would need approval, decide it on the call as written, with placeholders, so no dialog or classifier sees a key: your permission rules first, then (see ownPrompt) an allow or secret-box's own prompt. In plan mode such a call is refused until the plan ends; in dontAsk mode Claude Code's own answer stands. Off, Claude Code asks about the call with the real values in it, as before",
      "default": true
    },
    "ownPrompt": {
      "type": "boolean",
      "title": "Ask before each call that uses a key",
      "description": "With ownApproval on: when your permission rules don't decide a call that uses a key, show secret-box's own Allow/Deny prompt (placeholders only). Off, such a call is allowed without asking, and auto mode's classifier skips the whole command, not only the key",
      "default": false
    },
    "notify": {
      "type": "boolean",
      "title": "Say when something is hidden",
      "description": "Show a count on the tool row and a toast on a prompt",
      "default": true
    },
    "minEntropy": {
      "type": "number",
      "title": "Entropy floor (bits per character)",
      "description": "A mixed-case token above this floor is treated as a secret. Raise it to hide less",
      "default": 3.6
    },
    "minLength": {
      "type": "number",
      "title": "Length floor",
      "description": "The shortest token the entropy test looks at",
      "default": 24
    },
    "contextMinEntropy": {
      "type": "number",
      "title": "Entropy floor next to a key name",
      "description": "The floor used when the token sits after API_KEY=, \"token\":, Bearer and the like",
      "default": 3
    },
    "allow": {
      "type": "string",
      "title": "Never hide these",
      "description": "Exact strings to leave alone, separated by commas",
      "default": ""
    },
    "allowEmails": {
      "type": "string",
      "title": "Never hide these emails",
      "description": "Exact addresses, or a domain written as @example.com, separated by commas",
      "default": ""
    },
    "allowPrefixes": {
      "type": "string",
      "title": "Never hide tokens starting with",
      "description": "Extra id prefixes to treat as public, separated by commas (price_, prod_ and the other Stripe object ids are already public)",
      "default": ""
    },
    "allowUrlHosts": {
      "type": "string",
      "title": "Never hide URL paths on these hosts",
      "description": "Hosts such as app.todoist.com or *.example.com, separated by commas. The path of a link on one of them is kept as written; its query string is still scanned. Never list a host that puts credentials in the path",
      "default": ""
    },
    "denyPrefixes": {
      "type": "string",
      "title": "Always test tokens starting with",
      "description": "Prefixes to put back under the entropy test even though they look like a public id, separated by commas",
      "default": ""
    }
  }
}
